new:
    fn mcp_write_classifier_keeps_read_only_tools_claim_free() {
        assert!(mcp_write("authoring.apply"));
        assert!(mcp_write("scene.set_transform"));
        assert!(!mcp_write("project.describe"));
        assert!(!mcp_write("authoring.inspect"));
        assert!(!mcp_write("authoring.preview"));
    }

    #[test]
    fn benchmark_single_model_runtime_disables_routing_and_fallback_posture() {
        let runtime = NativeAgentRuntime::configured_benchmark_single_model(
            NativeModelConfig::Local(LocalModelConfig {
                endpoint: "http://127.0.0.1:11434".to_owned(),
                model: "exact-model:q4".to_owned(),
            }),
        );
        assert!(runtime.benchmark_single_model);
        assert_eq!(runtime.backend_config.model_id(), "exact-model:q4");
        assert!(runtime.routing_decisions.is_empty());
        assert_eq!(
            runtime.routing_policy_summary(),
            "single-model benchmark; routing and specialist fallback disabled"
        );
    }
}
